import{_ as a,a as t,b as r,c as s,d as i,e as o,f as l,g as n,h as u,i as c,j as p,k as d,l as m,m as h,n as _,o as f,p as g,q as b,r as v,s as y,t as q,u as z,v as x,w,x as k,y as A,z as E,A as P}from"./chunks/ScreenSaver2.C6Ib7NV6.js";import{_ as R}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as U}from"./chunks/UImenu.2mWyDoEW.js";import{_ as D}from"./chunks/3dots_menu.BrLPqWzo.js";import{_ as N,o as S,c as T,a3 as C}from"./chunks/framework.g9mfNVRQ.js";const J=JSON.parse('{"title":"Écran principal","description":"","frontmatter":{"source_hash":"3c47ed9511","source_commit":"ea9ce3a"},"headers":[],"relativePath":"fr/use/mainUI.md","filePath":"fr/use/mainUI.md"}'),I={name:"fr/use/mainUI.md"};function V(j,e,L,F,M,G){return S(),T("div",null,[...e[0]||(e[0]=[C('<h3 id="meet-the-user-interface" tabindex="-1">Découvrir l&#39;interface <a class="header-anchor" href="#meet-the-user-interface" aria-label="Permalink to &quot;Découvrir l&#39;interface {#meet-the-user-interface}&quot;">​</a></h3><p>Bienvenue dans xDrip !</p><img src="'+a+'" style="zoom:50%;"><p>Si vous venez d&#39;installer xDrip, commencez par quelques personnalisations de base :</p><ol><li><a href="./settings.html">Choisissez l&#39;unité d&#39;affichage de votre glycémie</a></li><li><a href="./alarms.html">Ajoutez des alarmes</a></li><li>Si xDrip est connecté à un capteur, <a href="./syncsetup.html">partagez les données avec un autre téléphone équipé de xDrip</a></li><li>Affichez xDrip sur le téléphone lorsque <a href="./display.html#numbered-wall-on-locked-screen">l&#39;écran est verrouillé</a></li><li>Ajoutez un <a href="#widget">widget</a> sur l&#39;écran d&#39;accueil de votre téléphone</li><li>Ajoutez une <a href="./../smartwatch/smartwatch.html">montre connectée</a></li><li>Partagez vos données avec votre diabétologue grâce à <a href="https://www.tidepool.org/" target="_blank" rel="noreferrer">Tidepool</a> : si vous avez un compte Tidepool, il suffit de <a href="./cloud.html#tidepool">configurer xDrip</a></li><li>Envoyez vos données vers <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> (recommandé)</li></ol><h3 id="basic-indications" tabindex="-1">Indications de base <a class="header-anchor" href="#basic-indications" aria-label="Permalink to &quot;Indications de base {#basic-indications}&quot;">​</a></h3><p>Voici les indications affichées par défaut lorsque xDrip reçoit des données.</p><img src="'+t+'" style="zoom:75%;"><ol><li>Depuis combien de temps la valeur a été reçue, et l&#39;écart de glycémie avec la valeur précédente.</li><li>La dernière valeur de glycémie mesurée.</li><li>La tendance par rapport à la mesure précédente.</li></ol><h5 id="trend-arrow" tabindex="-1">Flèche de tendance <a class="header-anchor" href="#trend-arrow" aria-label="Permalink to &quot;Flèche de tendance {#trend-arrow}&quot;">​</a></h5><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>La flèche indique la tendance par rapport à la mesure précédente. D&#39;autres applications CGM utilisent un algorithme pour calculer cette indication : le résultat peut donc être différent.<br> En cas de valeurs manquantes, la flèche peut indiquer une hausse ou une chute rapide : comparez toujours avec l&#39;indication <code>1</code>.</p></div><p>Vous pouvez personnaliser les informations affichées en <code>1</code> dans les <a href="./display.html#graph-settings">Paramètres de Graph</a>.</p><p>Vous pouvez <a href="#blood-drop-menu">personnaliser l&#39;aspect de la flèche de tendance</a>, mais pas son comportement (elle utilise toujours l&#39;écart avec la valeur précédente).</p><p>Voici comment s&#39;affiche la flèche de tendance classique, en fonction de l&#39;écart entre la glycémie précédente et la glycémie actuelle.</p><table tabindex="0"><thead><tr><th>Écart de glycémie (précédente et actuelle)</th><th></th></tr></thead><tbody><tr><td>Variation d&#39;au plus +/- 5 mg/dl (0,28 mmol/l)</td><td><img src="'+r+'" style="zoom:75%;"></td></tr><tr><td>Variation supérieure à la précédente et inférieure à +/- 10 mg/dl (0,56 mmol/l)</td><td><img src="'+s+'" style="zoom:75%;"></td></tr><tr><td>Variation supérieure à la précédente et inférieure à +/- 17,5 mg/dl (0,97 mmol/l)</td><td><img src="'+i+'" style="zoom:75%;"></td></tr><tr><td>Variation supérieure à la précédente</td><td><img src="'+o+'" style="zoom:75%;"></td></tr></tbody></table><h3 id="treatments" tabindex="-1">Traitements <a class="header-anchor" href="#treatments" aria-label="Permalink to &quot;Traitements {#treatments}&quot;">​</a></h3><p>Vous pouvez enregistrer des traitements avec l&#39;icône de seringue.</p><img src="'+l+'" style="zoom:75%;"><p>Ajoutez un ou plusieurs éléments à votre traitement.</p><h4 id="blood-test" tabindex="-1">Glycémie capillaire <a class="header-anchor" href="#blood-test" aria-label="Permalink to &quot;Glycémie capillaire {#blood-test}&quot;">​</a></h4><p>Elle s&#39;affiche dans l&#39;unité choisie dans xDrip.</p><img src="'+n+'" style="zoom:75%;"><h4 id="grams-of-carbs" tabindex="-1">Grammes de glucides <a class="header-anchor" href="#grams-of-carbs" aria-label="Permalink to &quot;Grammes de glucides {#grams-of-carbs}&quot;">​</a></h4><img src="'+u+'" style="zoom:75%;"><h4 id="units-of-insulin" tabindex="-1">Unités d&#39;insuline <a class="header-anchor" href="#units-of-insulin" aria-label="Permalink to &quot;Unités d&#39;insuline {#units-of-insulin}&quot;">​</a></h4><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>Si vous avez activé <a href="./predictions.html#multiple-insulin-types">plusieurs types d&#39;insuline</a>, sélectionnez aussi le type d&#39;insuline de ce traitement.</p></div><img src="'+c+'" style="zoom:75%;"><h4 id="time" tabindex="-1">Heure <a class="header-anchor" href="#time" aria-label="Permalink to &quot;Heure {#time}&quot;">​</a></h4><p>Et enfin l&#39;heure du traitement (si ce n&#39;est pas maintenant), au format 24 heures, avec ou sans séparateur.</p><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>Vous pouvez choisir une heure de traitement entre 23 heures dans le passé et 1 heure dans le futur.</p></div><img src="'+p+'" style="zoom:75%;"><p>Les traitements sont valides lorsque la coche verte apparaît en haut à droite. Appuyez dessus pour confirmer la saisie.</p><img src="'+d+'" style="zoom:75%;"><p>Un résumé s&#39;affiche. Appuyez sur l&#39;icône verte <code>+</code> pour confirmer ou sur l&#39;icône rouge <code>x</code> pour annuler.</p><img src="'+m+'" style="zoom:75%;"><p>Une fois validés, de nouveaux symboles apparaissent sur votre graphique.</p><p>Les unités et les glucides s&#39;affichent ainsi :</p><img src="'+h+'" style="zoom:75%;"><p>Et les glycémies capillaires ainsi (le symbole est carré, contrairement aux <a href="./../calibrate/calibrate.html">calibrations</a> qui sont rondes) :</p><img src="'+_+'" style="zoom:75%;"><h4 id="edit-and-delete" tabindex="-1">Modifier et supprimer <a class="header-anchor" href="#edit-and-delete" aria-label="Permalink to &quot;Modifier et supprimer {#edit-and-delete}&quot;">​</a></h4><p>Lorsqu&#39;ils sont visibles, vous pouvez supprimer les traitements ainsi :</p><ul><li>Appuyez sur le traitement, puis regardez en bas de l&#39;écran : appuyez sur Ajouter une note</li></ul><div style="background-color:black;color:white;text-align:left;">  18:45 Traitement <span style="color:cyan;float:right;">AJOUTER UNE NOTE </span></div><p>ou sur Glycémie.</p><div style="background-color:black;color:white;text-align:left;">  10:06 85 mg/dl <span style="color:cyan;float:right;">GLYCÉMIE </span></div><ul><li>Vous pouvez saisir une note ou appuyer sur EFFACER pour supprimer l&#39;entrée. Cela s&#39;applique aux glycémies capillaires, aux glucides et à l&#39;insuline.</li></ul><div class="admonition xdripitem"><p class="admonition-title">Remarque sur le traitement</p><p><span style="color:cyan;">_____________________________________________________________________________________</span><br><small>Utiliser la saisie vocale la prochaine fois</small> ☐</p><p><span style="color:cyan;float:left;">EFFACER </span><span style="color:cyan;float:right;">ANNULER TERMINÉ </span></p></div><p>Si vous appuyez sur une glycémie capillaire pour la modifier, vous pouvez aussi la convertir en calibration avec CALIBRER. C&#39;est possible si vous n&#39;avez pas sélectionné <strong>Never use them</strong> dans la <a href="./../calibrate/advancedcal.html">Calibration avancée</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Action de test sanguin</p><p>Que voulez-vous faire?</p><p><span style="color:cyan;float:left;">RIEN </span><span style="color:cyan;float:right;">EFFACER CALIBRER </span></p></div><h5 id="spoken-treatments" tabindex="-1">Traitements dictés <a class="header-anchor" href="#spoken-treatments" aria-label="Permalink to &quot;Traitements dictés {#spoken-treatments}&quot;">​</a></h5><p>Vous pouvez utiliser l&#39;icône du microphone pour saisir oralement des traitements ou des commandes avancées.</p><p>Un appui long sur l&#39;icône du microphone vous permet d&#39;écrire des <a href="./spokencommands.html">commandes avancées</a>.</p><h3 id="treatment-notes" tabindex="-1">Notes de traitement <a class="header-anchor" href="#treatment-notes" aria-label="Permalink to &quot;Notes de traitement {#treatment-notes}&quot;">​</a></h3><p>Indépendamment des traitements, vous pouvez saisir des notes.</p><img src="'+f+'" style="zoom:75%;"><p>Saisissez le commentaire de votre choix (par exemple des unités d&#39;insuline lente), ou utilisez l&#39;icône du microphone pour dicter la note.</p><div class="admonition xdripitem"><p class="admonition-title">Remarque sur le traitement</p><p><span style="color:cyan;">_____________________________________________________________________________________</span><br><small>Utiliser la saisie vocale la prochaine fois</small> ☐</p><p><span style="color:cyan;float:left;">EFFACER </span><span style="color:cyan;float:right;">ANNULER TERMINÉ </span></p></div><p>Elles sont ajoutées au graphique ainsi :</p><img src="'+g+'" style="zoom:75%;"><p>Appuyez dessus pour les modifier ou les supprimer.</p><h3 id="undo-and-redo" tabindex="-1">Annuler et Rétablir <a class="header-anchor" href="#undo-and-redo" aria-label="Permalink to &quot;Annuler et Rétablir {#undo-and-redo}&quot;">​</a></h3><ol><li>Annuler revient en arrière dans les simulations de traitements, les calibrations et les notes. Au bout de 30 minutes, le bouton disparaît à nouveau.</li><li>Rétablir avance de nouveau dans les simulations de traitements, les calibrations et les notes. Au bout de 30 minutes, le bouton disparaît à nouveau.</li></ol><img src="'+b+'" style="zoom:77%;"><h3 id="main-menu" tabindex="-1"><a href="./hamburger.html">Menu principal</a> <a class="header-anchor" href="#main-menu" aria-label="Permalink to &quot;[Menu principal](./hamburger) {#main-menu}&quot;">​</a></h3><p>Aussi appelé menu hamburger ou tiroir de navigation, c&#39;est le menu principal : vous y trouverez ou y ajouterez les actions les plus courantes, ainsi que tous les paramètres et personnalisations.</p><img src="'+R+'" style="zoom:75%;"><h3 id="blood-drop-menu" tabindex="-1">Menu goutte de sang <a class="header-anchor" href="#blood-drop-menu" aria-label="Permalink to &quot;Menu goutte de sang {#blood-drop-menu}&quot;">​</a></h3><p>Un appui long sur la zone centrale, entre le menu principal et le menu trois points, ouvre un autre menu pour personnaliser l&#39;interface.</p><img src="'+U+'" style="zoom:75%;"><h5 id="source-wizard-button" tabindex="-1">Bouton de l&#39;assistant source <a class="header-anchor" href="#source-wizard-button" aria-label="Permalink to &quot;Bouton de l&#39;assistant source {#source-wizard-button}&quot;">​</a></h5><p>Affiche le bouton qui vous guide dans le choix de la source de données, comme décrit <a href="./../install/datasource.html">ici</a>.</p><div class="admonition xdripitem"><p class="admonition-title"><span style="background-color:grey;color:white;">   DÉMARRER L&#39;ASSISTANT CONFIGURATION DE SOURCE </span></p></div><h5 id="show-time-buttons" tabindex="-1">Afficher les boutons de l&#39;heure <a class="header-anchor" href="#show-time-buttons" aria-label="Permalink to &quot;Afficher les boutons de l&#39;heure {#show-time-buttons}&quot;">​</a></h5><p>Ajoute une rangée de quatre préréglages pour la durée affichée sur le graphique principal : 24, 12, 6 et 3 heures.<br> Un appui long sur un bouton verrouille l&#39;affichage sur cette durée.</p><div class="admonition xdripitem"><p class="admonition-title"><span style="background-color:grey;color:white;">  24 HEURES </span>  <span style="background-color:grey;color:white;">  12 HEURES </span>  <span style="background-color:grey;color:white;">  6 HEURES </span>  <span style="background-color:grey;color:white;">  3 HEURES </span></p></div><h5 id="locked-time-period-always-used" tabindex="-1">Période de vérouillage toujours utilisée <a class="header-anchor" href="#locked-time-period-always-used" aria-label="Permalink to &quot;Période de vérouillage toujours utilisée {#locked-time-period-always-used}&quot;">​</a></h5><p>Utilise par défaut la dernière durée d&#39;affichage choisie.</p><h5 id="show-chart-preview" tabindex="-1">Afficher l&#39;aperçu du graphique <a class="header-anchor" href="#show-chart-preview" aria-label="Permalink to &quot;Afficher l&#39;aperçu du graphique {#show-chart-preview}&quot;">​</a></h5><p>Active ou désactive le petit graphique sur 24 heures en bas de l&#39;écran.</p><img src="'+v+'" style="zoom:75%;"><h5 id="show-collector-status" tabindex="-1">Afficher le statut du Collecteur <a class="header-anchor" href="#show-collector-status" aria-label="Permalink to &quot;Afficher le statut du Collecteur {#show-collector-status}&quot;">​</a></h5><p>Affiche sous le graphique principal des messages d&#39;information sur l&#39;état du collecteur.</p><img src="'+y+'" style="zoom:75%;"><h5 id="show-sensor-expiry" tabindex="-1">Afficher l&#39;expiration du capteur <a class="header-anchor" href="#show-sensor-expiry" aria-label="Permalink to &quot;Afficher l&#39;expiration du capteur {#show-sensor-expiry}&quot;">​</a></h5><p>Affiche sous le graphique principal le temps restant avant l&#39;expiration du capteur.</p><img src="'+q+'" style="zoom:75%;"><h5 id="show-graphical-trend-arrow" tabindex="-1">Afficher la flèche de tendance graphique <a class="header-anchor" href="#show-graphical-trend-arrow" aria-label="Permalink to &quot;Afficher la flèche de tendance graphique {#show-graphical-trend-arrow}&quot;">​</a></h5><p>Ajoute une option pour choisir d&#39;autres styles de flèche.</p><p>Utilisez la clé <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_wrench_grey600_48dp.png" style="width:3%;"> et le menu déroulant ▼ pour les sélectionner.<br> Les flèches en couleur comportent un curseur de teinte pour changer la couleur.</p><p>L&#39;angle des flèches de tendance graphiques dépend de l&#39;écart avec la valeur précédente (5 minutes), et non pas seulement plat/45/90 degrés comme les flèches classiques.</p><img src="'+z+'" style="zoom:90%;"><h3 id="three-dots-menu" tabindex="-1"><a href="./3dotsmenu.html">Menu trois points</a> <a class="header-anchor" href="#three-dots-menu" aria-label="Permalink to &quot;[Menu trois points](./3dotsmenu) {#three-dots-menu}&quot;">​</a></h3><p>Ce menu contient des raccourcis vers des paramètres et d&#39;autres fonctions spécifiques.</p><img src="'+D+'" style="zoom:75%;"><h3 id="widget" tabindex="-1">Widget <a class="header-anchor" href="#widget" aria-label="Permalink to &quot;Widget {#widget}&quot;">​</a></h3><p>Si votre téléphone prend en charge les widgets, faites un appui long sur une zone vide de l&#39;écran d&#39;accueil et sélectionnez Widgets.<br> Faites défiler les applications jusqu&#39;à trouver xDrip.</p><img src="'+x+'" style="zoom:75%;"><p>Gardez le doigt sur le widget et faites-le glisser à l&#39;emplacement souhaité.</p><img src="'+w+'" style="zoom:75%;"><p>Vous pouvez le redimensionner avec les points bleus.</p><img src="'+k+'" style="zoom:75%;"><p>Donnez-lui la taille qui vous convient. Vous pouvez ensuite personnaliser les couleurs et l&#39;aspect du contenu dans les <a href="./display.html">paramètres d&#39;affichage</a>.</p><img src="'+A+'" style="zoom:75%;"><h3 id="screensaver" tabindex="-1">Économiseur d&#39;écran <a class="header-anchor" href="#screensaver" aria-label="Permalink to &quot;Économiseur d&#39;écran {#screensaver}&quot;">​</a></h3><p>Si votre téléphone prend en charge cette fonction, vous pouvez activer xDrip comme économiseur d&#39;écran dans les paramètres Android.</p><img src="'+E+'" style="zoom:75%;"><p>Lorsque le téléphone est en charge, il affiche un petit graphique et la valeur de glycémie.</p><img src="'+P+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Dernière modification le 15/12/2024</em></a></p>',111)])])}const Q=N(I,[["render",V]]);export{J as __pageData,Q as default};
